/* ---------- ENGINE (no DOM) ---------- */
let RNG=Math.random;
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function hashStr(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function setSeed(s){RNG=s==null?Math.random:mulberry32(s);}
const rnd=()=>RNG();
const randInt=(a,b)=>a+Math.floor(rnd()*(b-a+1));
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
function gauss(){let u=0,v=0;while(!u)u=rnd();while(!v)v=rnd();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}

const FORMATS={
  odi:{key:"odi",name:"ODI World Cup",short:"ODI",ed:WC,balls:300,base:262,k:4.5,sd:32,lo:145,hi:428,allOut:200,maxOv:10,sr:88,
       mBase:4,mSd:38,mGap:3,cBase:4,cSd:36,cGap:5,cMin:150,ton:100},
  t20:{key:"t20",name:"T20 World Cup",short:"T20",ed:T20E,balls:120,base:160,k:2.8,sd:20,lo:85,hi:265,allOut:115,maxOv:4,sr:135,
       mBase:2,mSd:22,mGap:1.8,cBase:1,cSd:14,cGap:2,cMin:60,ton:50}
};
const ROLES={
  O:{name:"Opener",short:"OPN",c:"#3FA9F5"},M:{name:"Middle order",short:"MID",c:"#9B6BFF"},
  W:{name:"Wicketkeeper",short:"WK",c:"#F2C230"},A:{name:"All-rounder",short:"AR",c:"#14B8A6"},
  S:{name:"Spinner",short:"SPIN",c:"#FF8A3D"},F:{name:"Fast bowler",short:"PACE",c:"#E8384F"},X:{name:"Flex",short:"FLEX",c:"#FFFDF6"}
};
const SLOTS=[
  {id:"o1",role:"O"},{id:"o2",role:"O"},{id:"x1",role:"X"},{id:"x2",role:"X"},{id:"w",role:"W"},
  {id:"a1",role:"A"},{id:"a2",role:"A"},{id:"s1",role:"S"},{id:"s2",role:"S"},{id:"f1",role:"F"},{id:"f2",role:"F"}
];
const BIG8=["IND","AUS","ENG","PAK","SA","NZ","SL","WI"];

const _sq={};
function squad(fmt,year,code){
  const k=fmt+year+code;if(_sq[k])return _sq[k];
  const seen=new Set();
  _sq[k]=FORMATS[fmt].ed[year].teams[code].split("|").map(s=>{
    const m=s.trim().match(/^(.*) ([OMWASF])(\d\d)$/);
    return m?{name:m[1],role:m[2],r:+m[3],team:code,year:+year,fmt}:null;
  }).filter(p=>p&&!seen.has(p.name)&&seen.add(p.name)).sort((a,b)=>b.r-a.r);
  return _sq[k];
}
function cardKey(p){return p.fmt+p.year+p.team+"|"+p.name;}
function allCards(fmt){const out=[];for(const y in FORMATS[fmt].ed)for(const c in FORMATS[fmt].ed[y].teams)out.push(...squad(fmt,y,c));return out;}
function rarity(r){return r>=90?"legend":r>=84?"elite":r>=76?"star":"squad";}
const RARITY_NAME={legend:"Legend",elite:"Elite",star:"Star",squad:"Squad"};

function batVal(p){return p.role==="O"||p.role==="M"||p.role==="W"?p.r:p.role==="A"?p.r-5:28+(p.r-60)*0.15;}
function bowlVal(p){return p.role==="F"||p.role==="S"?p.r:p.role==="A"?p.r-5:20;}
function wavg(v,w){let s=0,t=0;v.forEach((x,i)=>{s+=x*w[i];t+=w[i];});return t?s/t:0;}
function rateXI(xi){
  const bats=xi.map(batVal).sort((a,b)=>b-a).slice(0,7);
  const bowls=xi.map(bowlVal).sort((a,b)=>b-a).slice(0,5);
  const bat=wavg(bats,[1.2,1.2,1.1,1,1,.8,.7]),bowl=wavg(bowls,[1.1,1.1,1,1,.8]);
  const ovr=(bat+bowl)/2-(xi.some(p=>p.role==="W")?0:3)-(xi.some(p=>p.role==="S")?0:1);
  return {bat:Math.round(bat),bowl:Math.round(bowl),ovr:Math.round(ovr*10)/10};
}
function bestXI(players){
  const xi=[];
  const take=(role,n)=>{for(const p of players){if(n<=0)break;if(p.role===role&&!xi.includes(p)){xi.push(p);n--;}}};
  take("W",1);take("O",2);take("M",3);take("A",2);take("S",1);take("F",2);
  while(xi.length<11){const rem=players.filter(p=>!xi.includes(p));if(!rem.length)break;
    rem.sort((a,b)=>Math.max(batVal(b),bowlVal(b))-Math.max(batVal(a),bowlVal(a)));xi.push(rem[0]);}
  return xi;
}
function makeTeam(code,name,color,xi,isUser,emoji){return {code,name,color,xi,isUser:!!isUser,emoji:emoji||null,...rateXI(xi)};}

/* ---------- MATCH ---------- */
const ROLE_ORDER={O:0,M:1,W:2,A:3,S:4,F:4};
function battingOrder(xi){return [...xi].sort((a,b)=>ROLE_ORDER[a.role]-ROLE_ORDER[b.role]||batVal(b)-batVal(a));}
const oversStr=b=>Math.floor(b/6)+(b%6?"."+(b%6):"");
function winProb(A,B,F){const t=F&&F.balls===120,k=t?8:3.2,c=t?.82:.93;return clamp(1/(1+Math.exp(-(A.ovr-B.ovr)/k)),1-c,c);}
function inn1(r,F,lost){
  const a=F.allOut,N=F.balls;
  const w=r<a?10:r<a*1.22?randInt(lost?8:7,10):randInt(lost?5:3,lost?10:9);
  return [w,w===10?(r<a*.95?randInt(Math.round(N*.7),Math.round(N*.92)):randInt(Math.round(N*.87),N-1)):N];
}
function inningsCard(batT,bowlT,inn,F){
  const used=battingOrder(batT.xi).slice(0,Math.min(11,inn.wkts+2));
  const extras=Math.max(0,Math.min(inn.runs-used.length,Math.round(inn.runs*(0.03+rnd()*0.05))));
  const pool=inn.runs-extras;
  const wt=used.map((p,i)=>Math.pow(Math.max(4,batVal(p)-30),1.6)*(0.2+rnd()*1.6)*(i<7?1:0.3));
  const sw=wt.reduce((a,b)=>a+b,0);
  const runs=wt.map(x=>Math.floor(pool*x/sw));
  runs[wt.indexOf(Math.max(...wt))]+=pool-runs.reduce((a,b)=>a+b,0);
  let balls=used.map((p,i)=>{const sr=F.sr*(0.7+rnd()*0.6)*(0.85+(batVal(p)-60)/220);return Math.max(1,Math.round(runs[i]*100/Math.max(40,sr)));});
  const f=clamp(inn.balls/balls.reduce((a,b)=>a+b,0),0.65,1.5);balls=balls.map(b=>Math.max(1,Math.round(b*f)));
  const bat=used.map((p,i)=>({name:p.name,r:runs[i],b:balls[i],no:i>=inn.wkts}));
  const bw=[...bowlT.xi].sort((a,b)=>bowlVal(b)-bowlVal(a)).slice(0,6);
  const maxB=F.maxOv*6;let left=inn.balls;const alloc=bw.map(()=>0);
  for(let i=0;i<bw.length&&left>0;i++){alloc[i]=Math.min(maxB,left);left-=alloc[i];}
  if(alloc[5]===0&&alloc[4]>=12&&rnd()<.6){const mv=6*randInt(1,F.maxOv===10?3:1);alloc[4]-=mv;alloc[5]+=mv;}
  const act=bw.map((p,i)=>({p,b:alloc[i]})).filter(x=>x.b>0);
  const wk=Math.max(0,inn.wkts-(inn.wkts>0&&rnd()<.25?1:0));
  const ww=act.map(x=>Math.pow(Math.max(5,bowlVal(x.p)-40),2)*x.b*(0.3+rnd()*1.4));
  const wks=act.map(()=>0);
  for(let k=0;k<wk;k++){let t=ww.reduce((a,b)=>a+b,0)*rnd(),j=0;for(;j<ww.length-1;j++){t-=ww[j];if(t<=0)break;}wks[j]++;}
  const cw=act.map(x=>x.b*(1.3-(bowlVal(x.p)-55)/120)*(0.85+rnd()*0.3)),scw=cw.reduce((a,b)=>a+b,0);
  const conc=inn.runs-Math.round(extras*0.6);
  const bowl=act.map((x,i)=>({name:x.p.name,o:oversStr(x.b),b:x.b,r:Math.round(conc*cw[i]/scw),w:wks[i]}));
  return {bat,bowl,extras};
}
function potm(res,W,F){
  const m={};const add=(n,s,l)=>{(m[n]=m[n]||{n,s:0,l:[]}).s+=s;m[n].l.push(l);};
  for(const inn of [res.first,res.second]){
    if(inn.team===W.code)inn.card.bat.forEach(x=>add(x.name,x.r*(F.balls===120?1.3:1)+(x.r>=F.ton/2?10:0)+(x.r>=F.ton?20:0),`${x.r}${x.no?"*":""} (${x.b})`));
    else inn.card.bowl.forEach(x=>{if(x.w>0)add(x.name,x.w*(F.balls===120?26:20)-x.r*(F.balls===120?0.5:0.25),`${x.w}/${x.r}`);});
  }
  const best=Object.values(m).sort((a,b)=>b.s-a.s)[0];
  if(best&&best.l.length>1)best.l=best.l.filter(l=>!/^\d\*? \(/.test(l));
  return best?{name:best.n,team:W.code,line:best.l.join(" & ")}:{name:W.xi[0].name,team:W.code,line:""};
}
function simMatch(A,B,F){
  const W=rnd()<winProb(A,B,F)?A:B,L=W===A?B:A;
  const bat1=rnd()<.5?A:B,bat2=bat1===A?B:A;
  const gap=Math.max(0,W.ovr-L.ovr),N=F.balls;
  const r1=Math.round(clamp(F.base+(bat1.bat-bat2.bowl)*F.k+gauss()*F.sd,F.lo,F.hi));
  let w1,b1,r2,w2,b2,summary;
  if(bat1===W){
    [w1,b1]=inn1(r1,F,false);
    const margin=Math.round(clamp(F.mBase+Math.abs(gauss())*F.mSd+gap*F.mGap,1,r1-F.lo*.45));
    r2=r1-margin;
    if(margin>(N===300?22:12)||rnd()<.5){w2=10;b2=randInt(Math.round(N*(r2>r1*.85?.82:.62)),N-1);}else{w2=randInt(5,9);b2=N;}
    summary=`won by ${margin} run${margin>1?"s":""}`;
  }else{
    [w1,b1]=inn1(r1,F,true);
    const wl=Math.round(clamp(3+gap/2+gauss()*1.8,1,9));
    w2=10-wl;r2=r1+randInt(1,N===300?6:5);
    b2=Math.round(clamp(N-(F.cBase+Math.abs(gauss())*F.cSd+gap*F.cGap),F.cMin,N-1));
    summary=`won by ${wl} wicket${wl>1?"s":""}`;
  }
  const first={team:bat1.code,runs:r1,wkts:w1,balls:b1},second={team:bat2.code,runs:r2,wkts:w2,balls:b2};
  first.card=inningsCard(bat1,bat2,first,F);second.card=inningsCard(bat2,bat1,second,F);
  const res={a:A.code,b:B.code,winner:W.code,loser:L.code,first,second,summary};
  res.potm=potm(res,W,F);
  return res;
}

/* ---------- TOURNAMENT ---------- */
const STAGES=["qf","sf","final"];
const STAGE_NAME={group:"Group stage",qf:"Quarter-final",sf:"Semi-final",final:"Final"};
const STAGE_SHORT={group:"G",qf:"QF",sf:"SF",final:"F"};
function newTournament(fmt,year,me){
  const F=FORMATS[fmt],ed=F.ed[year];
  const teams=Object.keys(ed.teams).map(c=>makeTeam(c,TEAMS[c][0],TEAMS[c][1],bestXI(squad(fmt,year,c)),false));
  const all=shuffle([...teams,me]);
  const T={fmt,F,year,teams:{},groups:{A:[],B:[]},results:[],phase:"group",queue:[],qi:0,path:[],out:null,champion:null,
    ko:{qf:[],sf:[],final:[]},tables:null,pendingNext:null,last:null,lastLoss:null};
  all.forEach((t,i)=>{T.teams[t.code]=t;T.groups[i%2?"B":"A"].push(t.code);});
  T.myGroup=T.groups.A.includes("YOU")?"A":"B";
  for(const g of ["A","B"]){const cs=T.groups[g];
    for(let i=0;i<cs.length;i++)for(let j=i+1;j<cs.length;j++){const a=cs[i],b=cs[j];
      if(a==="YOU"||b==="YOU")T.queue.push({a:"YOU",b:a==="YOU"?b:a,group:g});
      else T.results.push({...simMatch(T.teams[a],T.teams[b],F),group:g});}}
  T.queue.sort((x,y)=>T.teams[x.b].ovr-T.teams[y.b].ovr);
  return T;
}
function currentFixture(T){
  if(T.phase==="group")return T.queue[T.qi]||null;
  if(STAGES.includes(T.phase)&&!T.pendingNext)return T.ko[T.phase].find(m=>!m.res&&(m.a==="YOU"||m.b==="YOU"))||null;
  return null;
}
function playCurrent(T){
  const fx=currentFixture(T);if(!fx)return null;
  const res=simMatch(T.teams[fx.a],T.teams[fx.b],T.F),opp=fx.a==="YOU"?fx.b:fx.a,stage=T.phase;
  if(res.winner!=="YOU")T.lastLoss={res,stage,opp};
  if(T.phase==="group"){
    T.results.push({...res,group:fx.group});T.qi++;
    T.path.push({stage:"G",opp,won:res.winner==="YOU",res});
    if(T.qi>=T.queue.length)closeGroups(T);
  }else{
    fx.res=res;T.path.push({stage:STAGE_SHORT[T.phase],opp,won:res.winner==="YOU",res});
    if(res.winner!=="YOU"){T.out=T.phase;finishAll(T);}
    else if(T.phase==="final"){T.champion="YOU";T.phase="done";}
    else T.pendingNext=STAGES[STAGES.indexOf(T.phase)+1];
  }
  T.last={fx,res,stage};return res;
}
function table(T,g){
  const N=T.F.balls,rows={};T.groups[g].forEach(c=>rows[c]={code:c,p:0,w:0,l:0,pts:0,rf:0,bf:0,ra:0,bb:0});
  T.results.filter(r=>r.group===g).forEach(r=>{const f=r.first,s=r.second,fb=f.wkts===10?N:f.balls,sb=s.wkts===10?N:s.balls;
    rows[f.team].rf+=f.runs;rows[f.team].bf+=fb;rows[f.team].ra+=s.runs;rows[f.team].bb+=sb;
    rows[s.team].rf+=s.runs;rows[s.team].bf+=sb;rows[s.team].ra+=f.runs;rows[s.team].bb+=fb;
    rows[r.winner].p++;rows[r.loser].p++;rows[r.winner].w++;rows[r.winner].pts+=2;rows[r.loser].l++;});
  return Object.values(rows).map(x=>({...x,nrr:x.bf&&x.bb?(x.rf/(x.bf/6))-(x.ra/(x.bb/6)):0})).sort((a,b)=>b.pts-a.pts||b.nrr-a.nrr);
}
function closeGroups(T){
  T.tables={A:table(T,"A"),B:table(T,"B")};T.phase="table";
  const q=[...T.tables.A.slice(0,4),...T.tables.B.slice(0,4)].map(r=>r.code);
  if(!q.includes("YOU"))T.out="group";
}
function pairsFor(T,stage){
  if(stage==="qf"){const A=T.tables.A.map(r=>r.code),B=T.tables.B.map(r=>r.code);return [[A[0],B[3]],[B[1],A[2]],[B[0],A[3]],[A[1],B[2]]];}
  const prev=T.ko[stage==="sf"?"qf":"sf"].map(m=>m.res.winner);
  return stage==="sf"?[[prev[0],prev[1]],[prev[2],prev[3]]]:[[prev[0],prev[1]]];
}
function startKO(T,stage){
  T.phase=stage;T.pendingNext=null;
  T.ko[stage]=pairsFor(T,stage).map(([a,b])=>{const mine=a==="YOU"||b==="YOU";
    const m=mine?{a:"YOU",b:a==="YOU"?b:a,res:null}:{a,b,res:null};
    if(!mine)m.res=simMatch(T.teams[m.a],T.teams[m.b],T.F);return m;});
}
function finishAll(T){
  const start=T.phase==="table"||T.phase==="group"?0:STAGES.indexOf(T.phase)+1;
  for(let i=start;i<STAGES.length;i++)startKO(T,STAGES[i]);
  T.champion=T.ko.final[0].res.winner;T.phase="done";T.pendingNext=null;
}
const STAGE_BONUS={group:0,qf:150,sf:300,final:500,champ:900};
function outcomeKey(T){return T.champion==="YOU"?"champ":T.out;}
function dreamScore(T,me){return Math.round(me.ovr*10+T.path.filter(p=>p.won).length*40+STAGE_BONUS[outcomeKey(T)]);}
