/* ---- sound: tiny WebAudio synth ---- */
let AC=null;
function ac(){if(!S.sound)return null;try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();if(AC.state==="suspended")AC.resume();}catch(e){return null;}return AC;}
function tone(f,d=.06,type="square",v=.05,delay=0,f2){const a=ac();if(!a)return;const o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.value=f;
  const t=a.currentTime+delay;if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+d);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g).connect(a.destination);o.start(t);o.stop(t+d+.02);}
function roar(d=.9,v=.12){const a=ac();if(!a)return;const len=Math.floor(a.sampleRate*d),b=a.createBuffer(1,len,a.sampleRate),ch=b.getChannelData(0);
  for(let i=0;i<len;i++)ch[i]=(Math.random()*2-1)*Math.sin(Math.PI*i/len);const s=a.createBufferSource(),f=a.createBiquadFilter(),g=a.createGain();
  f.type="bandpass";f.frequency.value=900;f.Q.value=.6;g.gain.value=v;s.buffer=b;s.connect(f).connect(g).connect(a.destination);s.start();}
const sfx={tick:()=>tone(1500,.02,"square",.018),land:()=>[523,659,784].forEach((f,i)=>tone(f,.14,"triangle",.07,i*.07)),
  pick:()=>tone(660,.09,"triangle",.08),legend:()=>{[523,659,784,1047,1319].forEach((f,i)=>tone(f,.2,"triangle",.08,i*.06));roar(1.1,.1);},
  win:()=>{[392,523,659,784].forEach((f,i)=>tone(f,.18,"triangle",.07,i*.07));roar(1,.09);},lose:()=>[392,330,262].forEach((f,i)=>tone(f,.22,"triangle",.06,i*.12)),
  coin:()=>[988,1319].forEach((f,i)=>tone(f,.12,"square",.04,i*.08)),deal:()=>tone(300+VR()*200,.04,"sawtooth",.012),
  six:()=>{tone(300,.35,"sawtooth",.04,0,1400);roar(.8,.11);},wicket:()=>{tone(180,.18,"square",.08,0,60);tone(1200,.05,"square",.04,.05);roar(.7,.1);},
  fifty:()=>{[659,880,1047].forEach((f,i)=>tone(f,.15,"triangle",.07,i*.08));roar(.9,.08);},
  rattle:()=>tone(2200+VR()*600,.012,"square",.012)};
