/* ---- confetti ---- */
const FX={p:[],on:false};
function confetti(n=110,colors=["#FFC93D","#FF3B4E","#35D6FF","#22C55E","#FFFFFF","#8B5CF6"]){
  if(REDUCED)return;const c=$("#fx"),d=window.devicePixelRatio||1;c.width=innerWidth*d;c.height=innerHeight*d;
  for(let i=0;i<n;i++)FX.p.push({x:innerWidth/2+(VR()-.5)*120,y:innerHeight*.35,vx:(VR()-.5)*14,vy:-VR()*14-4,s:6+VR()*7,r:VR()*6,vr:(VR()-.5)*.4,c:colors[i%colors.length],life:0});
  if(!FX.on){FX.on=true;requestAnimationFrame(fxLoop);}}
function fxLoop(){const c=$("#fx"),x=c.getContext("2d"),d=window.devicePixelRatio||1;x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,innerWidth,innerHeight);
  FX.p=FX.p.filter(p=>p.life<160&&p.y<innerHeight+40);
  FX.p.forEach(p=>{p.life++;p.vy+=.35;p.vx*=.99;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/3,p.s,p.s*.66);x.restore();});
  if(FX.p.length)requestAnimationFrame(fxLoop);else{FX.on=false;x.clearRect(0,0,innerWidth,innerHeight);}}

