function initials(n){const p=n.split(" ");return (p[0][0]+(p.length>1?p[p.length-1][0]:"")).toUpperCase();}
function splitName(n){const p=n.split(" ");return p.length>1?[p.slice(0,-1).join(" "),p[p.length-1]]:["",n];}
const TIER_TAG={legend:"★ LEGEND",elite:"◆ ELITE"};
function cardHTML(p,o={}){const [fn,ln]=splitName(p.name),rar=rarity(p.r),tag=o.btn?"button":"div";
  const bv=Math.round(batVal(p)),wv="OMW".includes(p.role)?"–":Math.round(bowlVal(p));
  return `<${tag} class="tc r-${rar} ${o.off?"off":""}" style="--i:${o.i||0}" ${o.btn?`data-i="${o.i}" ${o.off?'aria-disabled="true"':""} aria-label="${esc(p.name)}, ${TEAMS[p.team][0]}, ${RARITY_NAME[rar]} ${ROLES[p.role].name}, rated ${p.r}, ${p.year}"`:""}>
   <span class="tc-body"><span class="tc-rays"></span><span class="tc-flagbg">${flagSVG(p.team)}</span>${TIER_TAG[rar]?`<span class="tc-tier">${TIER_TAG[rar]}</span>`:""}
    <span class="tc-ovr">${p.r}</span><span class="tc-role">${ROLES[p.role].short}</span><span class="tc-yr"><small>${FORMATS[p.fmt].short}</small>${p.year}</span>
    <span class="tc-team">${flagSVG(p.team,"flag tc-fl")}<b>${p.team}</b></span>
    <span class="tc-art">${glyph(p.role)}</span>
    <span class="tc-name"><small>${esc(fn)||"&nbsp;"}</small><b>${esc(ln)}</b></span>
    <span class="tc-stats"><span>BAT <b>${bv}</b></span><span>BOWL <b>${wv}</b></span></span>
   </span>${o.isNew?`<span class="newb">NEW</span>`:""}</${tag}>`;}
function miniHTML(p,pop){
  return `<div class="mc r-${rarity(p.r)} ${pop?"pop":""}" title="${esc(p.name)}, ${TEAMS[p.team][0]} ${p.year}"><div class="b"><span class="mfl">${flagSVG(p.team,"flag")}</span><span class="o">${p.r}</span><span class="rl">${ROLES[p.role].short}</span><span class="tm">${p.team}</span><span class="g">${glyph(p.role)}</span><span class="n">${esc(surname(p.name))}</span><span class="yr">'${String(p.year).slice(2)}</span></div></div>`;}
function emptyMini(s){return `<div class="mc empty"><div class="el"><span class="plus">+</span>${s.role==="X"?"FLEX":ROLES[s.role].short}</div></div>`;}
function tiltCards(root){if(REDUCED||!root)return;
  root.addEventListener("pointermove",e=>{const c=e.target.closest(".tc");if(!c||c.classList.contains("off"))return;const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;
    c.style.transform=`perspective(500px) rotateY(${(x-.5)*16}deg) rotateX(${(.5-y)*16}deg)`;});
  root.addEventListener("pointerout",e=>{const c=e.target.closest(".tc");if(c)c.style.transform="";});}
function assignSlots(xi){const out={},left=[...xi];
  const put=(test)=>SLOTS.forEach(s=>{if(out[s.id])return;const i=left.findIndex(p=>test(s,p));if(i>=0){out[s.id]=left[i];left.splice(i,1);}});
  put((s,p)=>s.role===p.role);put((s,p)=>s.role==="X");put(()=>true);return out;}

