  if(st.feat.includes("pavilion"))s+=`<rect x="18" y="${B-58}" width="100" height="58" fill="#9B4A36"/><path d="M14 ${B-58}L68 ${B-74}L122 ${B-58}Z" fill="#2E4B3C"/>${Array.from({length:6},(_,i)=>`<rect x="${26+i*15}" y="${B-48}" width="8" height="14" rx="4" fill="#F2E2B8"/><rect x="${26+i*15}" y="${B-26}" width="8" height="12" rx="4" fill="#F2E2B8"/>`).join("")}<rect x="62" y="${B-82}" width="12" height="10" fill="#E8E2D0"/>`;
  if(st.feat.includes("pod"))s+=`<path d="M300 ${B-40}V${B-6}M340 ${B-40}V${B-6}" stroke="#C8CDD6" stroke-width="3"/><ellipse cx="320" cy="${B-58}" rx="44" ry="20" fill="#E9EDF2"/><path d="M282 ${B-58}h76" stroke="#3A4A66" stroke-width="5"/>`;
  const palm=x=>`<path d="M${x} ${B}q4 -26 -2 -52" stroke="#3A2A1C" stroke-width="3" fill="none"/>${[-60,-20,20,60,100,140].map(a=>`<path d="M${x-2} ${B-52}q${(Math.cos(a*Math.PI/180)*14).toFixed(1)} ${(-6+Math.sin(a*Math.PI/180)*6).toFixed(1)} ${(Math.cos(a*Math.PI/180)*24).toFixed(1)} ${(8+Math.sin(a*Math.PI/180)*10).toFixed(1)}" stroke="#2F6B3A" stroke-width="3.4" fill="none" stroke-linecap="round"/>`).join("")}`;
  if(st.feat.includes("palms"))s+=palm(14)+palm(388)+palm(40);
  if(st.feat.includes("trees"))[[10,30],[48,22],[352,24],[392,32]].forEach(([x,r])=>s+=`<circle cx="${x}" cy="${B-r*.7}" r="${r}" fill="#1E4430"/><circle cx="${x-r*.3}" cy="${B-r}" r="${r*.6}" fill="#25553B"/>`);
  if(flag){const fy=top-62;s+=`<path d="M200 ${top-8}V${fy-2}" stroke="#D9DEE7" stroke-width="2"/><circle cx="200" cy="${fy-3}" r="2" fill="#FFC93D"/><g class="flutter"><svg x="201" y="${fy}" width="42" height="28" viewBox="0 0 30 20" preserveAspectRatio="none">${flagInner(flag)}</svg></g>`;}
