/* ================= SPINNERS ================= */
const ROU=["#3A4A63","#5A3E46","#3F5A4B","#5F5440","#463D5C","#2F4F5A"];
function rouletteHTML(labels){const n=labels.length,seg=360/n,R=98,Ri=70;
  let s=`<div class="roul"><svg viewBox="-125 -125 250 250" class="rsvg" aria-hidden="true"><defs>
    <radialGradient id="rwood" cx=".5" cy=".5" r=".5"><stop offset=".86" stop-color="#5A3E2B"/><stop offset=".93" stop-color="#8B6545"/><stop offset="1" stop-color="#3D2A1D"/></radialGradient>
    <radialGradient id="rfelt" cx=".45" cy=".4" r=".6"><stop offset="0" stop-color="#2F5A45"/><stop offset="1" stop-color="#173527"/></radialGradient>
    <linearGradient id="rgold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#F3E3B0"/><stop offset=".5" stop-color="#B8893A"/><stop offset="1" stop-color="#E8C877"/></linearGradient></defs>
    <circle r="124" fill="url(#rwood)"/><circle r="113" fill="#2A2018"/><circle r="111" fill="#3B2E22"/><circle r="${R+2}" fill="none" stroke="url(#rgold)" stroke-width="1.6"/>
    <g class="rrot">`;
  labels.forEach((l,i)=>{const a0=(-90-seg/2+i*seg)*Math.PI/180,a1=(-90+seg/2+i*seg)*Math.PI/180;
    s+=`<path d="M${(Ri*Math.cos(a0)).toFixed(2)} ${(Ri*Math.sin(a0)).toFixed(2)}L${(R*Math.cos(a0)).toFixed(2)} ${(R*Math.sin(a0)).toFixed(2)}A${R} ${R} 0 0 1 ${(R*Math.cos(a1)).toFixed(2)} ${(R*Math.sin(a1)).toFixed(2)}L${(Ri*Math.cos(a1)).toFixed(2)} ${(Ri*Math.sin(a1)).toFixed(2)}A${Ri} ${Ri} 0 0 0 ${(Ri*Math.cos(a0)).toFixed(2)} ${(Ri*Math.sin(a0)).toFixed(2)}Z" fill="${ROU[i%ROU.length]}" stroke="url(#rgold)" stroke-width=".8"/>`;
    s+=`<g transform="rotate(${-90+i*seg}) translate(${(R+Ri)/2} 0) rotate(90)"><text text-anchor="middle" dominant-baseline="central" class="rlbl" font-size="${n>14?10:12}" fill="#F3E6C4">${l}</text></g>`;});
  s+=`<circle r="${Ri}" fill="url(#rfelt)" stroke="url(#rgold)" stroke-width="1.4"/><circle r="${Ri-14}" fill="none" stroke="rgba(243,227,176,.25)" stroke-width="1"/>
    <g fill="url(#rgold)"><circle r="14"/>${[0,90,180,270].map(a=>`<g transform="rotate(${a})"><rect x="-2.2" y="-44" width="4.4" height="32" rx="2"/><circle cy="-46" r="4.5"/></g>`).join("")}</g><circle r="6" fill="#3B2E22"/></g></svg>
   <div class="rball"></div><button class="rbtn" aria-label="Drop the ball"><span>DROP<br>THE BALL</span></button></div>`;
  return s;}
function makeRoulette(host,labels){host.innerHTML=rouletteHTML(labels);const el=$(".roul",host);
  return {el,rot:$(".rrot",el),ball:$(".rball",el),btn:$(".rbtn",el),n:labels.length,angle:0};}
function spinRoulette(r,k){return new Promise(res=>{ac();r.btn.hidden=true;const n=r.n,seg=360/n,size=r.el.offsetWidth,c=size/2,sc=size/250;
  const trackR=105*sc,pocketR=84*sc,D=REDUCED?900:5600,drop=REDUCED?0:650;
  const w0=r.angle,wEnd=w0+360*(1.6+VR()*.6),target=wEnd-90+k*seg+(VR()-.5)*seg*.25;
  const bStart=-90,bTotal=(((bStart-target)%360)+360)%360+360*(4+Math.floor(VR()*2));
  const easeW=t=>1-Math.pow(1-t,2.6),easeB=t=>1-Math.pow(1-t,2.2),t0=performance.now();let lastP=-1;
  const place=(ang,rad)=>{const a=ang*Math.PI/180;r.ball.style.transform=`translate(${c+rad*Math.cos(a)}px,${c+rad*Math.sin(a)}px)`;};
  r.ball.style.opacity=1;
  const step=now=>{const el=now-t0;
    if(el<drop){const t=el/drop,b=Math.abs(Math.cos(t*Math.PI*1.25))*(1-t);place(-90,trackR+(c*1.05)*(1-t)*(1-t)+b*14*sc);requestAnimationFrame(step);return;}
    const t=Math.min(1,(el-drop)/(D-drop)),wa=w0+(wEnd-w0)*easeW(t);r.rot.style.transform=`rotate(${wa}deg)`;
    const ba=bStart-bTotal*easeB(t);let rad=trackR;
    if(t>.68){const u=(t-.68)/.32;rad=trackR-(trackR-pocketR)*Math.min(1,u*1.4)+Math.sin(u*Math.PI*5)*(1-u)*5*sc;}
    place(ba,rad);
    const rel=(((ba-wa+90+seg/2)%360)+360)%360,p=Math.floor(rel/seg);if(p!==lastP){if(lastP!==-1&&t<.97)sfx.rattle();lastP=p;}
    if(t<1)requestAnimationFrame(step);else{r.angle=wEnd%360;r.rot.style.transform=`rotate(${r.angle}deg)`;place(target-wEnd+r.angle,pocketR);sfx.land();buzz(30);res(k);}};
  requestAnimationFrame(step);});}
const REP=12;
function reelHTML(codes){let t="";for(let r=0;r<REP;r++)codes.forEach(c=>t+=`<div class="rt"><span class="rf">${flagSVG(c)}</span><b>${c}</b><small>${esc(TEAMS[c][0])}</small></div>`);
  return `<div class="reel"><div class="reel-strip">${t}</div><i class="reel-mark"></i></div>`;}
function makeReel(host,codes){host.innerHTML=reelHTML(codes);const el=$(".reel",host);return {el,strip:$(".reel-strip",el),n:codes.length,x:0};}
function spinReel(rl,k){return new Promise(res=>{ac();const tiles=rl.strip.children,TW=tiles[1].offsetLeft-tiles[0].offsetLeft,win=rl.el.offsetWidth,n=rl.n,loop=n*TW;
  let cur=rl.x;while(cur<-loop*2)cur+=loop;rl.strip.style.transition="none";rl.strip.style.transform=`translateX(${cur}px)`;void rl.strip.offsetWidth;
  const ti=(REP-2)*n+k,xt=-(ti*TW+TW/2-win/2)+(VR()-.5)*TW*.3,dur=REDUCED?500:3000+VR()*500;
  rl.strip.style.transition=`transform ${dur}ms cubic-bezier(.12,.72,.1,1)`;requestAnimationFrame(()=>rl.strip.style.transform=`translateX(${xt}px)`);
  let last=-1;const t0=performance.now();
  const loopf=()=>{const m=new DOMMatrixReadOnly(getComputedStyle(rl.strip).transform),idx=Math.floor((-m.e+win/2)/TW);if(idx!==last){if(last!==-1)sfx.tick();last=idx;}
    if(performance.now()-t0<dur)requestAnimationFrame(loopf);};requestAnimationFrame(loopf);
  setTimeout(()=>{rl.x=xt;[...tiles].forEach(t=>t.classList.remove("hit"));tiles[ti].classList.add("hit");sfx.land();buzz(30);res(k);},dur+50);});}

const SPOTS={o1:[40,14],o2:[60,14],x1:[15,36],a1:[33,36],a2:[67,36],x2:[85,36],s1:[24,61],w:[50,62],s2:[76,61],f1:[38,85],f2:[62,85]};
function shortN(n){if(n.length<=12)return n;const p=n.split(" ");return p.length>1?p[0][0]+". "+p.slice(1).join(" "):n;}

/* ---- binder + achievements ---- */
function binder(){return store.get("binder",{});}
function addToBinder(p){const b=binder(),k=cardKey(p);if(b[k])return false;b[k]=1;store.set("binder",b);
  if(Object.keys(b).length>=200&&unlock("collector"))toast("🏅 Achievement: Collector");return true;}
const ACH=[
 ["first","⚡","First win","Win a match at any World Cup."],["champ","🏆","World champion","Lift any World Cup."],
 ["invincible","🛡️","Invincibles","Win the cup without losing a game."],["double","🎯","Double act","Win both an ODI and a T20 World Cup."],
 ["giant","🪓","Giant killer","Win the cup with a lower OVR than that year's real champions."],["legends","🌟","Hall of fame","Fit four Legends (90+) into one XI."],
 ["underdog","🐺","Underdog story","Reach the semis with four players from outside the big eight."],["bigmatch","🎖️","Big-match player","Have one of your XI named Player of the Final."],
 ["daily3","🔥","Daily habit","Play the Daily three days in a row."],["collector","📚","Collector","Collect 200 cards for your collection."]
];
function unlock(id){const a=store.get("ach",{});if(a[id])return false;a[id]=todayStr();store.set("ach",a);return true;}
function checkAch(T,me){const got=[],u=id=>{if(unlock(id))got.push(id);},k=outcomeKey(T);
  if(T.path.some(p=>p.won))u("first");
  if(k==="champ"){u("champ");if(T.path.every(p=>p.won))u("invincible");
    const tf=store.get("titleFmts",{});tf[T.fmt]=1;store.set("titleFmts",tf);if(tf.odi&&tf.t20)u("double");
    if(me.ovr<T.teams[FORMATS[T.fmt].ed[T.year].champ].ovr)u("giant");
    if(T.ko.final[0].res.potm.team==="YOU")u("bigmatch");}
  if(me.xi.filter(p=>p.r>=90).length>=4)u("legends");
  if(["sf","final","champ"].includes(k)&&me.xi.filter(p=>!BIG8.includes(p.team)).length>=4)u("underdog");
  return got;}

/* ---- daily ---- */
function dailyInfo(){const date=todayStr(),seed=hashStr("dt-daily-"+date),r=mulberry32(seed);
  const fmt=r()<.5?"odi":"t20",ys=Object.keys(FORMATS[fmt].ed),year=+ys[Math.floor(r()*ys.length)],codes=Object.keys(FORMATS[fmt].ed[year].teams);
  return {date,no:dailyNo(date),fmt,year,seq:Array.from({length:120},()=>codes[Math.floor(r()*codes.length)]),si:0};}
function dailyDone(){const d=store.get("daily",null);return d&&d.date===todayStr()?d:null;}
function bumpStreak(){const s=store.get("streak",{last:null,n:0}),t=todayStr(),y=new Date();y.setDate(y.getDate()-1);
  if(s.last===t)return s.n;s.n=s.last===todayStr(y)?s.n+1:1;s.last=t;store.set("streak",s);if(s.n>=3&&unlock("daily3"))toast("🏅 Achievement: Daily habit");return s.n;}
function streakNow(){const s=store.get("streak",{last:null,n:0}),y=new Date();y.setDate(y.getDate()-1);return s.last===todayStr()||s.last===todayStr(y)?s.n:0;}



/* ---- re-rolls ---- */
function rerollsLeft(){return S.daily||S.duel?0:S.free+S.bank;}
function bumpPill(){const p=$("#rr");if(p){p.textContent=rerollsLeft();const b=p.closest(".pill");b.classList.remove("bump");void b.offsetWidth;b.classList.add("bump");}
  document.querySelectorAll("[data-rr]").forEach(e=>e.textContent=rerollsLeft()?`${rerollsLeft()} left`:"Get more");}
function lockedReroll(label){return `<button class="gb gb-lock rrlock" disabled><span class="gb-in"></span><span class="gb-t">${IC.lock}${label} · ${S.duel?"NOT IN DUELS":"NOT IN THE DAILY"}</span></button>`;}
function rerollBtn(label,id){const n=rerollsLeft();return `<button class="reroll" id="${id}"><span class="dice" aria-hidden="true">🎲</span><span class="rr-t"><b>${label}</b><small data-rr>${n?n+" left":"Get more"}</small></span></button>`;}
function spendRerolls(n,after){const have=S.free+S.bank;if(have>=n){let r=n;const f=Math.min(S.free,r);S.free-=f;r-=f;S.bank-=r;store.set("bank",S.bank);bumpPill();sfx.coin();after();}
  else{toast(`You need ${n} re-rolls, you have ${have}`);openStore(()=>spendRerolls(n,after));}}
function useReroll(action){if(S.daily){toast("The Daily has no re-rolls");return;}if(S.duel){toast("Duels have no re-rolls");return;}
  if(S.free>0)S.free--;else if(S.bank>0){S.bank--;store.set("bank",S.bank);}else{openStore(()=>useReroll(action));return;}
  bumpPill();action();}
function openStore(after){
  if(S.daily&&S.screen!=="home"){toast("The Daily has no re-rolls");return;}
  const m=modal(`<div class="dice-big" aria-hidden="true">${DICEI}</div><h3>${rerollsLeft()===0?"Out of re-rolls":"Get more re-rolls"}</h3>
   <p>${after?"Grab one and your re-roll fires straight away.":"Every draft starts with one free re-roll. Stock up to chase the perfect XI."}</p>
   <div class="packs"><button class="pack" data-pack="ad"><span>📺 Watch a short ad</span><b>+1</b><em>Free</em></button>
    <button class="pack" data-pack="5"><span>Handful</span><b>+5</b><em>₹29</em></button>
    <button class="pack best" data-pack="15"><span>Big bag, best value</span><b>+15</b><em>₹69</em></button></div>
   <p class="fine">Prototype: purchases are simulated, nothing is charged.</p><button class="btn ghost" data-close>Not now</button>`);
  m.querySelectorAll("[data-pack]").forEach(b=>b.onclick=()=>{const k=b.dataset.pack;
    if(k==="ad"){let n=3;m.querySelector(".pb").innerHTML=`<div class="dice-big">📺</div><h3>Ad playing</h3><p>${after?"Your re-roll fires":"Your re-roll lands"} in <b id="cd">${n}</b>s</p>`;
      const iv=setInterval(()=>{n--;const c=$("#cd");if(c)c.textContent=n;if(n<=0){clearInterval(iv);grant(1,after);}},1000);}else grant(+k,after);});}
function grant(n,after){S.bank+=n;store.set("bank",S.bank);closeModal();sfx.coin();bumpPill();toast(`+${n} re-roll${n>1?"s":""} added`);if(after)setTimeout(after,350);}

/* ================= ENERGY ================= */
const EMAX=5,REGEN=30*60*1000;
function energy(){let s=store.get("energy",{e:EMAX,t:Date.now()});const now=Date.now();
  if(s.e<EMAX){const g=Math.floor((now-s.t)/REGEN);if(g>0){s.e=Math.min(EMAX,s.e+g);s.t=s.e>=EMAX?now:s.t+g*REGEN;store.set("energy",s);}}else if(s.e>=EMAX&&s.t>now)s.t=now;
  return s;}
function nextCanMs(){const s=energy();return s.e>=EMAX?0:Math.max(0,REGEN-(Date.now()-s.t));}
function spendEnergy(){const s=energy();if(s.e<=0)return false;if(s.e>=EMAX)s.t=Date.now();s.e--;store.set("energy",s);return true;}
function addEnergy(n){const s=energy();s.e=Math.min(EMAX*3,s.e+n);if(s.e>=EMAX)s.t=Date.now();store.set("energy",s);}
function withEnergy(fn){if(spendEnergy()){refreshHUD();fn();}else openEnergy(()=>{if(spendEnergy()){refreshHUD();fn();}});}
const fmtT=ms=>{const t=Math.ceil(ms/1000),h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;return (h?h+":":"")+String(m).padStart(h?2:1,"0")+":"+String(s).padStart(2,"0");};
const CAN=`<svg class="can" viewBox="0 0 24 32" aria-hidden="true"><defs><linearGradient id="cang" x1="0" x2="1"><stop offset="0" stop-color="#1D4ED8"/><stop offset=".45" stop-color="#60A5FA"/><stop offset="1" stop-color="#1E3A8A"/></linearGradient></defs><rect x="3" y="3.5" width="18" height="26.5" rx="4" fill="url(#cang)"/><rect x="4.5" y="1" width="15" height="4" rx="2" fill="#E2E8F0"/><rect x="3" y="9" width="18" height="2" fill="#FFE34D" opacity=".9"/><path d="M13.6 12.5l-5.4 8.2h4.1l-1 6.3 5.6-9h-4.2z" fill="#FFE34D"/></svg>`;
function openEnergy(after){
  const ms=nextCanMs();
  const m=modal(`<div class="big-can" aria-hidden="true">${CAN}</div><h3>${energy().e?"Grab an energy drink":"Out of energy"}</h3>
   <p>Every World Cup run uses one can. Cans refill on their own${ms?`, next one in <b data-en-next>${fmtT(ms)}</b>`:""}. The Daily never needs energy.</p>
   <div class="packs"><button class="pack" data-can="ad"><span>📺 Watch a short ad</span><b>+1</b><em>Free</em></button>
    <button class="pack" data-can="5"><span>Six-pack</span><b>+5</b><em>₹49</em></button>
    <button class="pack best" data-can="12"><span>Team cooler, best value</span><b>+12</b><em>₹99</em></button></div>
   <p class="fine">Prototype: purchases are simulated, nothing is charged.</p><button class="btn ghost" data-close>Not now</button>`);
  m.querySelectorAll("[data-can]").forEach(b=>b.onclick=()=>{const k=b.dataset.can;
    const give=n=>{addEnergy(n);closeModal();sfx.coin();refreshHUD();toast(`+${n} energy`);if(after)setTimeout(after,300);};
    if(k==="ad"){let n=3;m.querySelector(".pb").innerHTML=`<div class="big-can">${CAN}</div><h3>Ad playing</h3><p>Your can lands in <b id="cd">${n}</b>s</p>`;
      const iv=setInterval(()=>{n--;const c=$("#cd");if(c)c.textContent=n;if(n<=0){clearInterval(iv);give(1);}},1000);}else give(+k);});}

