  x.save();x.translate(cx,yb+12);x.scale(1,.3);{const R=w*.86,sg=x.createRadialGradient(0,0,0,0,0,R);sg.addColorStop(0,"rgba(0,22,8,.6)");sg.addColorStop(.35,"rgba(0,22,8,.42)");sg.addColorStop(.7,"rgba(0,22,8,.12)");sg.addColorStop(1,"rgba(0,22,8,0)");x.fillStyle=sg;x.beginPath();x.arc(0,0,R,0,7);x.fill();}x.restore();
  x.save();x.shadowColor="rgba(0,10,4,.55)";x.shadowBlur=34;x.shadowOffsetY=w*.1;rr(x,X,Y,w,h,w*.09);x.fillStyle="rgba(0,0,0,.4)";x.fill();x.restore();
  x.save();if(t.glow){x.shadowColor=t.glow;x.shadowBlur=30;}rr(x,X,Y,w,h,w*.09);x.fillStyle=grad(x,X,Y,X+w,Y+h,t.edge);x.fill();x.restore();
  rr(x,X+4,Y+4,w-8,h-8,w*.075);x.fillStyle=grad(x,X,Y,X+w*.6,Y+h,t.cb);x.fill();
  x.save();rr(x,X+4,Y+4,w-8,h-8,w*.075);x.clip();
  if(img.flag[p.team]){x.globalAlpha=.32;x.drawImage(img.flag[p.team],X,Y+h*.62,w,h*.38);x.globalAlpha=1;}
  x.fillStyle="rgba(255,255,255,.14)";x.beginPath();x.moveTo(X,Y+h*.42);x.lineTo(X+w,Y+h*.16);x.lineTo(X+w,Y+h*.27);x.lineTo(X,Y+h*.53);x.fill();
  if(img.g[p.role])x.drawImage(img.g[p.role],X+w*.36,Y+w*.36,w*.6,w*.6);x.restore();
  x.fillStyle=t.ct;x.textAlign="left";x.textBaseline="alphabetic";x.font=`italic 800 ${Math.round(w*.42)}px 'Barlow Condensed'`;x.fillText(p.r,X+w*.08,Y+w*.43);
  x.font=`800 ${Math.round(w*.13)}px 'Barlow Condensed'`;x.globalAlpha=.85;x.fillText(ROLES[p.role].short,X+w*.1,Y+w*.59);x.globalAlpha=1;
  if(img.flag[p.team]){const fw=w*.28,fh=fw*.67,fx=X+w-fw-w*.08,fy=Y+w*.09;x.drawImage(img.flag[p.team],fx,fy,fw,fh);x.lineWidth=2;x.strokeStyle="rgba(255,255,255,.8)";x.strokeRect(fx,fy,fw,fh);
    x.textAlign="center";x.font=`800 ${Math.round(w*.12)}px 'Barlow Condensed'`;x.fillStyle=t.ct;x.fillText(p.team,fx+fw/2,fy+fh+w*.13);}
  x.textAlign="center";const n=surname(p.name).toUpperCase();let fs=Math.round(w*.25);do{x.font=`italic 800 ${fs}px 'Barlow Condensed'`;fs--;}while(x.measureText(n).width>w*.88&&fs>12);
