  x.beginPath();x.ellipse(cx,cy,560,450,0,0,7);x.fillStyle="#0B1A33";x.fill();
  x.save();x.beginPath();x.ellipse(cx,cy,540,432,0,0,7);x.clip();for(let i=0;i<16;i++){const y0=cy-432+i*54;x.fillStyle=i%2?"#1A8A49":"#20A055";x.fillRect(0,y0,1080,55);}
  const rg=x.createRadialGradient(cx,cy-160,0,cx,cy-160,560);rg.addColorStop(0,"rgba(255,255,255,.18)");rg.addColorStop(1,"rgba(255,255,255,0)");x.fillStyle=rg;x.fillRect(0,0,1080,1920);x.restore();
  x.beginPath();x.ellipse(cx,cy,540,432,0,0,7);x.lineWidth=9;x.strokeStyle="rgba(255,255,255,.92)";x.stroke();
  x.save();x.setLineDash([16,13]);x.beginPath();x.ellipse(cx,cy+10,380,290,0,0,7);x.lineWidth=4;x.strokeStyle="rgba(255,255,255,.4)";x.stroke();x.restore();
  x.beginPath();x.moveTo(cx-34,cy-250);x.lineTo(cx+34,cy-250);x.lineTo(cx+56,cy+20);x.lineTo(cx-56,cy+20);x.closePath();x.fillStyle=grad(x,0,cy-250,0,cy+20,["#D9C28E","#C9AE74"]);x.fill();
  x.fillStyle=W;x.fillRect(cx-44,cy-226,88,4);x.fillRect(cx-62,cy-8,124,5);
  const rows=[[["o1",430],["o2",650],1000,148],[["x1",150],["a1",395],["a2",685],["x2",930],1230,160],[["s1",255],["w",540],["s2",825],1475,172],[["f1",400],["f2",680],1735,186]];
  rows.forEach(r=>{const w=r[r.length-1],yb=r[r.length-2];r.slice(0,-2).forEach(([id,px])=>{const p=me.xi[SLOTS.findIndex(s=>s.id===id)];drawCard(x,p,px,yb,w,img);});});
  x.textAlign="center";x.textBaseline="alphabetic";x.font="italic 800 104px 'Barlow Condensed'";const dw=x.measureText("DREAM ").width,tw=x.measureText("TEAM").width,sx=540-(dw+tw)/2;
  x.textAlign="left";x.fillStyle=W;x.fillText("DREAM ",sx,128);x.fillStyle=grad(x,0,50,0,130,["#FFF1B0","#FFC93D","#FF8A00"]);x.fillText("TEAM",sx+dw,128);
  x.textAlign="center";x.font="700 34px Barlow";x.fillStyle="#C9D6EA";x.fillText(`${T.F.name.toUpperCase()} ${T.year}  ·  ${st.name.toUpperCase()}${S.daily?`  ·  DAILY #${S.daily.no}`:""}`,540,182);
  const champ=label==="World champions";x.font="italic 800 66px 'Barlow Condensed'";const lw=x.measureText(label.toUpperCase()).width+90;
  x.save();if(champ){x.shadowColor="rgba(255,201,61,.8)";x.shadowBlur=40;}rr(x,540-lw/2,212,lw,92,46);x.fillStyle=champ?grad(x,0,212,0,304,["#FFE070","#FFB21E"]):grad(x,0,212,0,304,["#FF6274","#E01E37"]);x.fill();x.restore();
  x.fillStyle=champ?"#2A1700":W;x.textBaseline="middle";x.fillText(label.toUpperCase(),540,261);x.textBaseline="alphabetic";
