  x.textAlign="left";let fs=54;const tn=me.name.toUpperCase();do{x.font=`italic 800 ${fs}px 'Barlow Condensed'`;fs-=2;}while(x.measureText(tn).width>560&&fs>30);x.fillStyle=W;x.fillText(tn,214,1812);
  const wins=T.path.filter(p=>p.won).length;x.font="600 28px Barlow";x.fillStyle="#C9D6EA";x.fillText(`OVR ${Math.round(me.ovr)}  ·  W-L ${wins}-${T.path.length-wins}  ·  Score ${score}`,214,1852);
