/* ---- BINDER + CABINET ---- */
function vBinder(app){const b=binder();let tab=S.binderTab||"odi";
  const draw=()=>{const F=FORMATS[tab],years=Object.keys(F.ed),all=allCards(tab),have=all.filter(p=>b[cardKey(p)]).length;
    app.innerHTML=`<div class="screen">${topbar()}<h2 class="t6">CARD <span>COLLECTION</span></h2><p class="s6">Every player you draft joins your collection.</p>
     <div class="seg" role="tablist"><button role="tab" data-t="odi" aria-selected="${tab==="odi"}">ODI</button><button role="tab" data-t="t20" aria-selected="${tab==="t20"}">T20</button></div>
     <div class="panel"><div class="ph">${F.name}<small>${have} of ${all.length} collected</small></div><div class="pb">${years.map(y=>{const cs=Object.keys(F.ed[y].teams).flatMap(c=>squad(tab,y,c)),h=cs.filter(p=>b[cardKey(p)]).length;
       return `<button class="prog-row" data-y="${y}" aria-expanded="false"><b>${y}</b><div class="meter"><i style="--c:var(--green);width:${h/cs.length*100}%"></i></div><span class="small">${h}/${cs.length}</span></button><div class="bgrid" data-g="${y}" hidden></div>`;}).join("")}</div></div></div>`;
    app.querySelectorAll("[data-t]").forEach(x=>x.onclick=()=>{tab=S.binderTab=x.dataset.t;draw();});
    app.querySelectorAll("[data-y]").forEach(x=>x.onclick=()=>{const y=x.dataset.y,gr=app.querySelector(`[data-g="${y}"]`),open=gr.hidden;gr.hidden=!open;x.setAttribute("aria-expanded",open);
      if(open&&!gr.innerHTML){const cs=Object.keys(F.ed[y].teams).flatMap(c=>squad(tab,y,c)).sort((a,c)=>c.r-a.r);gr.innerHTML=cs.map(p=>b[cardKey(p)]?miniHTML(p):`<div class="cardback" title="Not collected yet"></div>`).join("");}});};
  draw();}
function vCabinet(app){const a=store.get("ach",{});
  app.innerHTML=`<div class="screen">${topbar()}<h2 class="h1">Trophy shelf</h2><div class="statrow"><div class="stat"><b>${store.get("best",0)||"–"}</b><span>Best score</span></div><div class="stat"><b>${store.get("runs",0)}</b><span>Series played</span></div><div class="stat"><b>${store.get("titles",0)}</b><span>World Cups</span></div></div><p class="sub" style="margin-top:12px">${Object.keys(a).length} of ${ACH.length} achievements unlocked.</p>
   <div class="panel"><div class="ph">Achievements</div><div class="pb">${ACH.map(([id,ic,n,d])=>`<div class="ach ${a[id]?"on":""}"><i aria-hidden="true">${ic}</i><div><b>${n}</b><span>${d}${a[id]?` Unlocked ${a[id]}.`:""}</span></div></div>`).join("")}</div></div></div>`;}

const IMG={hero:"data:image/webp;base64,",crowd:"data:image/webp;base64,",mrf:"data:image/webp;base64,"};
/* ================= v6: canvas design ================= */
const TAG6={legend:"★ LEGEND",elite:"◆ ELITE",star:"STAR",squad:"SQUAD"};
function statVals(p){return [Math.round(batVal(p)),"OMW".includes(p.role)?"–":Math.round(bowlVal(p))];}
/* medium card: pick-your-player, collection, champions */
function cardHTML(p,o={}){const rar=rarity(p.r),[fn,ln]=splitName(p.name),tag=o.btn?"button":"div",[bv,wv]=statVals(p);
  return `<${tag} class="tc2 t-${rar} ${o.off?"off":""}" style="--i:${o.i||0}" ${o.btn?`data-i="${o.i}" ${o.off?'aria-disabled="true"':""} aria-label="${esc(p.name)}, ${TEAMS[p.team][0]}, ${RARITY_NAME[rar]} ${ROLES[p.role].name}, rated ${p.r}"`:""}>
   <span class="tc2-in"><span class="c-band" aria-hidden="true">${flagSVG(p.team)}</span><span class="c-ovr">${p.r}</span><span class="c-role">${ROLES[p.role].short}</span><span class="c-yr">${p.year}</span>
   <span class="c-fl">${flagSVG(p.team)}<b>${p.team}</b></span>${rar==="legend"||rar==="elite"?`<span class="c-tag">${TAG6[rar]}</span>`:""}
   <span class="c-art">${glyph(p.role)}</span><span class="c-nm"><small>${esc(fn)||"&nbsp;"}</small><b>${esc(ln)}</b></span>
   <span class="c-st">BAT <b>${bv}</b><i></i>BOWL <b>${wv}</b></span></span>${o.isNew?'<span class="c-new">NEW</span>':""}</${tag}>`;}
/* small card: on the ground, collection grid */
function miniHTML(p,pop){const rar=rarity(p.r);
  return `<div class="mc2 t-${rar} ${pop?"pop":""}" title="${esc(p.name)}, ${TEAMS[p.team][0]} ${p.year}"><div class="mc2-in"><span class="m-ovr">${p.r}</span><span class="m-role">${ROLES[p.role].short}</span><span class="m-fl">${flagSVG(p.team)}</span><span class="m-art">${glyph(p.role)}</span><span class="m-nm">${esc(surname(p.name))}</span></div></div>`;}
/* large card: the reveal */
function bigCardHTML(p,isNew){const rar=rarity(p.r),[fn,ln]=splitName(p.name),[bv,wv]=statVals(p);
  return `<div class="bc t-${rar}"><div class="bc-in">${rar==="legend"||rar==="elite"?'<i class="bc-rays"></i>':""}<span class="bc-band">${flagSVG(p.team)}</span>
   <span class="b-ovr">${p.r}</span><span class="b-role">${ROLES[p.role].short}</span><span class="b-yr"><small>${FORMATS[p.fmt].short}</small>${p.year}</span>
   <span class="b-fl">${flagSVG(p.team)}<b>${p.team}</b></span><span class="b-tag">${TAG6[rar]}</span><span class="b-art">${glyph(p.role)}</span>
   <span class="b-nm"><small>${esc(fn)||"&nbsp;"}</small><b>${esc(ln)}</b></span><span class="b-st"><span>BAT <b>${bv}</b></span><span>BOWL <b>${wv}</b></span></span><i class="bc-shine"></i></div>${isNew?'<span class="c-new big">NEW</span>':""}</div>`;}
function emptyMini(s){return `<div class="mc2 empty"><span>+</span><b>${s.role==="X"?"FLEX":ROLES[s.role].short}</b></div>`;}

/* chamfered gloss button */
function gbtn(label,kind="cyan",id="",extra=""){return `<button class="gb gb-${kind}" ${id?`id="${id}"`:""} ${extra}><span class="gb-in"></span><span class="gb-gl"></span><span class="gb-t">${label}</span></button>`;}
