/* ---------- YEAR: prize wheel ---------- */
const WCOL=["#3B2A9E","#1E6FA8","#6D28D9","#0F766E","#4338CA","#9D2E6F"];
function wheelHTML(years){const n=years.length,seg=360/n,R=104,fs=n>8?16:22;let s="";
  years.forEach((y,i)=>{const a0=(-90-seg/2+i*seg)*Math.PI/180,a1=(-90+seg/2+i*seg)*Math.PI/180;
    s+=`<path data-i="${i}" d="M0 0L${(R*Math.cos(a0)).toFixed(2)} ${(R*Math.sin(a0)).toFixed(2)}A${R} ${R} 0 0 1 ${(R*Math.cos(a1)).toFixed(2)} ${(R*Math.sin(a1)).toFixed(2)}Z" fill="${WCOL[i%WCOL.length]}" stroke="#0B1A33" stroke-width="2"/>`;
    s+=`<g transform="rotate(${-90+i*seg}) translate(${(R*.66).toFixed(1)} 0) rotate(90)"><text data-t="${i}" text-anchor="middle" dominant-baseline="central" class="wh-l" font-size="${fs}" fill="#FFFFFF">${y}</text></g>`;});
  let bulbs="";for(let i=0;i<24;i++){const a=i*15*Math.PI/180;bulbs+=`<circle class="wb ${i%2?"alt":""}" cx="${(110.5*Math.cos(a)).toFixed(2)}" cy="${(110.5*Math.sin(a)).toFixed(2)}" r="2.8"/>`;}
  return `<div class="wh2 idle"><svg class="wh2-base" viewBox="-125 -125 250 250" aria-hidden="true"><defs><linearGradient id="whRim" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFF1B0"/><stop offset=".5" stop-color="#C8871A"/><stop offset="1" stop-color="#FFE070"/></linearGradient>
   <linearGradient id="whHit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFF0A0"/><stop offset=".55" stop-color="#FFC93D"/><stop offset="1" stop-color="#E08A00"/></linearGradient>
   <radialGradient id="whGl" cx=".42" cy=".3" r=".75"><stop offset="0" stop-color="#FFFFFF" stop-opacity=".32"/><stop offset=".6" stop-color="#FFFFFF" stop-opacity="0"/></radialGradient></defs>
   <circle r="121" fill="#0B1A33"/><circle r="116" fill="none" stroke="url(#whRim)" stroke-width="6"/></svg>
   <div class="wh2-rot"><svg viewBox="-125 -125 250 250" aria-hidden="true">${s}<circle r="${R}" fill="url(#whGl)"/></svg></div>
   <svg class="wh2-top" viewBox="-125 -125 250 250" aria-hidden="true">${bulbs}<defs><linearGradient id="whPt" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFF1B0"/><stop offset="1" stop-color="#FF9F1C"/></linearGradient></defs><g class="wh2-ptr"><path d="M0 -94 L-13 -120 A15 15 0 1 1 13 -120 Z" fill="url(#whPt)" stroke="#FFFFFF" stroke-width="2" stroke-linejoin="round"/><circle cx="0" cy="-121" r="5" fill="#0B1A33"/></g></svg>
   <button class="wh2-hub" aria-label="Spin the wheel"><span>SPIN</span></button></div>`;}
function makeWheel2(host,years){host.innerHTML=wheelHTML(years);const el=$(".wh2",host);return {el,rot:$(".wh2-rot",el),hub:$(".wh2-hub",el),ptr:$(".wh2-ptr",el),n:years.length,angle:0};}
function spinWheel2(w,k){return new Promise(res=>{ac();w.el.classList.remove("idle");w.el.classList.add("spinning");
  w.el.querySelectorAll("[data-i]").forEach(p=>p.setAttribute("fill",WCOL[+p.dataset.i%WCOL.length]));w.el.querySelectorAll("[data-t]").forEach(t=>t.setAttribute("fill","#FFFFFF"));
  const seg=360/w.n,jit=(VR()-.5)*seg*.5,delta=((-k*seg+jit-w.angle)%360+360)%360,final=w.angle+(REDUCED?1:5+Math.floor(VR()*3))*360+delta,dur=REDUCED?600:4000+Math.floor(VR()*600);
  w.rot.style.transition=`transform ${dur}ms cubic-bezier(.12,.7,.08,1)`;requestAnimationFrame(()=>{w.rot.style.transform=`rotate(${final}deg)`;});
  let last=-1;const t0=performance.now();
  const loop=()=>{const tf=getComputedStyle(w.rot).transform;let ang=0;if(tf&&tf!=="none"){const m=new DOMMatrixReadOnly(tf);ang=Math.atan2(m.b,m.a)*180/Math.PI;}
    const idx=((Math.round(-ang/seg)%w.n)+w.n)%w.n;if(idx!==last){if(last!==-1){sfx.tick();if(!REDUCED&&w.ptr.animate)w.ptr.animate([{transform:"rotate(-14deg)"},{transform:"rotate(0)"}],{duration:130,easing:"ease-out"});}last=idx;}
    if(performance.now()-t0<dur)requestAnimationFrame(loop);};requestAnimationFrame(loop);
  setTimeout(()=>{w.angle=final;w.el.classList.remove("spinning");const p=w.el.querySelector(`[data-i="${k}"]`),t=w.el.querySelector(`[data-t="${k}"]`);if(p)p.setAttribute("fill","url(#whHit)");if(t)t.setAttribute("fill","#2A1700");sfx.land();buzz(30);res(k);},dur+60);});}
