/* ---------- LIVE: crowd placards, wickets and milestones only ---------- */
function moments(inn,F){const N=F.balls,fr=inn.balls/N,bat=inn.card.bat,ev=[],outs=bat.filter(b=>!b.no),by=[];
  inn.card.bowl.forEach(b=>{for(let i=0;i<b.w;i++)by.push(b.name);});while(by.length<inn.wkts)by.push(null);by.sort(()=>VR()-.5);
  const wt=Array.from({length:inn.wkts},()=>(.04+VR()*.9)*fr).sort((a,b)=>a-b);if(inn.wkts===10)wt[9]=fr;
  const top=[...bat].sort((a,b)=>b.r-a.r);
  wt.forEach((t,i)=>{const b=outs[i]||{name:"the tail",r:0},w=by[i];if(i===0||b.r>=30||b===top[0])ev.push({t,type:"w",who:w,bat:b.name,r:b.r,sub:w?`${surname(w)} gets ${surname(b.name)} for ${b.r}`:`${surname(b.name)} run out for ${b.r}`});});
  bat.forEach(b=>{if(b.r>=100)ev.push({t:(.78+VR()*.18)*fr,type:"100",bat:b.name,r:b.r,b:b.b,no:b.no,sub:`${surname(b.name)} raises a hundred`});else if(b.r>=50)ev.push({t:(.45+VR()*.45)*fr,type:"50",bat:b.name,r:b.r,b:b.b,no:b.no,sub:`${surname(b.name)} brings up a fifty`});});
  const ms=ev.filter(e=>e.type==="50"||e.type==="100").slice(0,2),ws=ev.filter(e=>e.type==="w"&&!(inn.wkts===10&&e.t>=fr-1e-9)).slice(0,3);
  const pops=[...ms,...ws].sort((a,b)=>a.t-b.t);
  if(inn.wkts===10)pops.push({t:fr,type:"all",team:inn.team,runs:inn.runs,ov:oversStr(inn.balls),sub:`All out for ${inn.runs}`});
  return {pops,wt};}
function placards(a1,a2,b1,b2){const s=$("#moment");if(!s)return;const p1=$(".plc.p1",s),p2=$(".plc.p2",s);
  const fit=t=>t.length>9?" xs":t.length>7?" sm":"";p1.innerHTML=`<b class="${fit(a1)}">${esc(a1)}</b>${a2?`<small>${esc(a2)}</small>`:""}`;p2.innerHTML=`<b class="${fit(b1)}">${esc(b1)}</b>${b2?`<small>${esc(b2)}</small>`:""}`;
  if(!REDUCED&&!S.ff)[p1,p2].forEach(p=>{p.classList.remove("in");void p.offsetWidth;p.classList.add("in");});}
function showPop(ev){const N=S.T.F.balls,ov=oversStr(Math.round(ev.t*N));
  if(ev.type==="w")placards("OUT!","",ev.who?surname(ev.who).toUpperCase():"RUN OUT",`${surname(ev.bat)} ${ev.r}`);
  else if(ev.type==="50"||ev.type==="100")placards(ev.type==="50"?"FIFTY!":"100!","",surname(ev.bat).toUpperCase(),`${ev.r}${ev.no?"*":""} (${ev.b})`);
  else placards("ALL OUT","",teamOf(ev.team).isUser?"YOU":ev.team,`${ev.runs} (${ev.ov})`);
  const cap=$("#mcap");if(cap)cap.innerHTML=`<span class="ov">${ov}</span>${esc(ev.sub)}`;
  const k=$("#kml");if(k){const lab={w:"Wicket","50":"Fifty","100":"Hundred",all:"All out"}[ev.type];k.insertAdjacentHTML("afterbegin",`<div class="kmr"><span class="ov">${ov}</span><i class="kd k${ev.type}"></i><span><b class="k${ev.type}">${lab}</b> · ${esc(ev.sub)}</span></div>`);
    const rows=k.querySelectorAll(".kmr");if(rows.length>4)rows[rows.length-1].remove();}
  ({"w":sfx.wicket,"50":sfx.fifty,"100":sfx.fifty,"all":sfx.wicket}[ev.type])();buzz(ev.type==="w"?[40,30,40]:20);S.km.push(ev);}
