  if(scorePanel&&scorePanel.classList.contains("panel")){const ach=scorePanel.querySelector(".badges");
    scorePanel.outerHTML=`<div class="r6-score"><span><small>DREAM SCORE</small><b>${score}</b>${S.pb?'<em>NEW BEST</em>':""}</span><span class="r6-b">${ach?ach.innerHTML:`<span class="badge">${label}</span>`}</span></div>`;}
  const two=app.querySelector(".actions.two"),one=two&&two.nextElementSibling;
  if(two)two.outerHTML=`<div class="actions two">${gbtn("SHARE CARD","cyan","share")}${gbtn("WHATSAPP","green","copy",'aria-label="Copy result for WhatsApp"')}<button id="save" hidden></button></div>`;
  if(one&&one.classList.contains("actions")){one.outerHTML=`<div class="actions">${S.daily?gbtn("PLAY A FREE DRAFT","gold","free"):gbtn(`DRAFT AGAIN <span class="cancost">${CAN}1</span>`,"gold","again")}${S.daily?"":gbtn(`${DICEI}TRY ${T.year} DRAFT AGAIN <span class="cancost">${DICEI.replace('width="20" height="20"','width="14" height="14"')}2</span>`,"violet","same")}</div>`;}
  /* rebind the buttons that were replaced */
  const ag=$("#again");if(ag)ag.onclick=()=>withEnergy(()=>startRun(T.fmt,false));
  const sm=$("#same");if(sm)sm.onclick=()=>spendRerolls(2,()=>{setSeed(null);S.picks={};S.free=1;S.T=null;S.daily=null;go("draft");});
  const fr=$("#free");if(fr)fr.onclick=()=>{S.daily=null;go("home");};
  $("#copy").onclick=()=>copyText(S.share);
  const story=$("#story");let blob=null;const waitBlob=()=>new Promise(r=>{const t=setInterval(()=>{if(story.src&&story.src.startsWith("data:")){clearInterval(t);fetch(story.src).then(x=>x.blob()).then(r);}},150);});
  waitBlob().then(b=>blob=b);
