/* ================= v7: your team first, streak, levels, leaderboard ================= */
/* ---------- the player's team (set once, at the start) ---------- */
function myTeam(){return store.get("myTeam",null);}
function saveTeam(t){store.set("myTeam",{name:(t.name||"").trim().slice(0,20)||"Dream XI",flag:{...t.flag,c:[...t.flag.c]}});store.set("lastTeam",myTeam());}
function cleanFlag(f){if(!f||typeof f!=="object")return null;const hex=/^#[0-9A-Fa-f]{6}$/;
  if(!FLAG_PATTERNS.includes(f.p)||!EMBLEMS.includes(f.e)||!Array.isArray(f.c)||f.c.length!==3||!f.c.every(c=>hex.test(c)))return null;return {p:f.p,c:[...f.c],e:f.e};}

/* waving flag: the flag image cut into strips that ripple */
function flutterFlag(flag,w,h,extra=""){const url=svgURL(flagSVG({isUser:true,flag})),n=16,sw=w/n;let s="";
  for(let i=0;i<n;i++)s+=`<i style="left:${(i*sw).toFixed(2)}px;width:${(sw+.6).toFixed(2)}px;background:url('${url}') ${(-i*sw).toFixed(2)}px 0/${w}px ${h}px;animation-delay:${(-i*.11).toFixed(2)}s;--a:${(i/n*7).toFixed(2)}px"></i>`;
  return `<div class="ffl ${extra}" style="width:${w}px;height:${h}px" role="img" aria-label="Your team flag">${s}<b class="ffl-sh"></b></div>`;}

/* ---------- 20 levels ---------- */
const LEVELS=[["Net Bowler","Bowling in the nets"],["Twelfth Man","Carrying the drinks"],["Tailender","Number eleven, bat in hand"],["Nightwatchman","Sent in to survive"],
 ["Club Cricketer","Weekend whites"],["County Pro","Paid to play"],["First-Class Regular","Four-day grind"],["Debutant","First cap, first game"],["Capped Player","A regular in the XI"],
 ["Strike Bowler","Takes the new ball"],["Opener","Faces the first ball"],["Finisher","Wins it at the death"],["All-Rounder","Bats and bowls"],["Centurion","Raises the bat"],
 ["Match Winner","Player of the Match"],["Vice-Captain","Next in line"],["Captain","Leads the XI"],["World Cup Winner","Lifts the trophy"],["Hall of Famer","Legend of the game"],["Living Legend","The Don of Dream Team"]];
const LV_XP=n=>250*n*(n-1);               /* total XP to reach level n (1-based): L2 500, L10 22,500, L20 95,000 */
const LV_REWARD=n=>n===20?5:n%5===0?3:1;  /* re-rolls granted when you reach level n */
function levelOf(xp){let n=1;while(n<20&&xp>=LV_XP(n+1))n++;const cur=LV_XP(n),nxt=n<20?LV_XP(n+1):cur;
  return {n,name:LEVELS[n-1][0],tag:LEVELS[n-1][1],xp,cur,nxt,pct:n<20?Math.round((xp-cur)/(nxt-cur)*100):100,need:nxt-xp};}
function xpInfo(){const L=levelOf(store.get("xp",0));return {lv:L.n,pct:L.pct,name:L.name};}
function levelUp(oldXp,newXp){const a=levelOf(oldXp).n,b=levelOf(newXp).n;if(b<=a)return;let n=0;for(let i=a+1;i<=b;i++)n+=LV_REWARD(i);
  S.bank+=n;store.set("bank",S.bank);const L=levelOf(newXp);
  setTimeout(()=>{sfx.legend();confetti(120);const m=modal(`<div class="lvup"><div class="lvup-n">${L.n}</div><p class="eyb">LEVEL UP</p><h3>${esc(L.name.toUpperCase())}</h3><p>${esc(L.tag)}. You earned <b>+${n} re-roll${n>1?"s":""}</b>.</p>${gbtn("NICE","gold","lvok","data-close")}</div>`);
    $("#lvok",m).onclick=closeModal;},1400);}

/* ---------- shared leaderboard (each player writes only their own row) ---------- */
const LB={state:"loading",db:null,uid:null,rows:[],pushed:""};
async function lbInit(){
  if(!(window.claude&&typeof window.claude.use==="function")){LB.state="off";lbPaint();return;}
  try{const [db,u]=await Promise.all([window.claude.use("db"),window.claude.use("user")]);
    if(!db){LB.state="off";lbPaint();return;}
    LB.db=db;LB.uid=u?await u.id():null;try{LB.canWrite=u?await u.can("data.write"):null;}catch(e){LB.canWrite=null;}
    db.collection("lb").orderBy("best","desc").limit(50).onSnapshot(s=>{LB.rows=s.docs.map(d=>({id:d.id,...d.data()}));LB.state="on";lbPaint();},()=>{LB.state="off";lbPaint();});
    lbPush();}catch(e){LB.state="off";lbPaint();}}
async function lbPush(){if(!LB.db||!LB.uid)return;const t=myTeam(),best=store.get("best",0);if(!t||!best)return;
  const xp=store.get("xp",0),d={name:t.name.slice(0,20),flag:cleanFlag(t.flag),best,lv:levelOf(xp).n,ts:Date.now()},k=JSON.stringify([d.name,d.flag,d.best,d.lv]);
  if(k===LB.pushed)return false;LB.pushed=k;try{await LB.db.doc("lb/"+LB.uid).set(d);LB.canWrite=true;return true;}catch(e){LB.pushed="";LB.canWrite=false;lbPaint();return false;}}
function lbRows(){return LB.rows.filter(r=>typeof r.best==="number"&&r.best>0).map((r,i)=>({rank:i+1,me:r.id===LB.uid,uid:r.id,name:String(r.name||"Unnamed XI").slice(0,20),
  flag:cleanFlag(r.flag)||{p:"tri-v",c:["#475569","#94A3B8","#1E293B"],e:"none"},best:Math.round(r.best),lv:Math.min(20,Math.max(1,Math.round(+r.lv||1)))}));}
function lbRowHTML(r){return `<div class="lbr ${r.me?"me":""} ${r.rank<=3?"top r"+r.rank:""}"><span class="lb-rk">${r.rank<=3?`<i>${r.rank}</i>`:r.rank}</span><span class="lb-fl">${flagSVG({isUser:true,flag:r.flag})}</span>
  <span class="lb-nm"><b>${esc(r.name)}${r.me?' <em>YOU</em>':""}</b><small>LV ${r.lv} · ${esc(LEVELS[r.lv-1][0])}</small></span><span class="lb-sc">${r.best.toLocaleString("en-IN")}</span></div>`;}
function lbHTML(full){const best=store.get("best",0),t=myTeam();
  if(LB.state==="loading")return `<p class="lb-note">Loading the leaderboard…</p>`;
  if(LB.state==="off"){return `${best&&t?lbRowHTML({rank:"–",me:true,name:t.name,flag:t.flag,best,lv:levelOf(store.get("xp",0)).n}):""}<p class="lb-note">Connecting to the leaderboard… Your best is kept on this device meanwhile.</p>`;}
  const rows=lbRows();if(!rows.length)return `<p class="lb-note">No scores yet. Finish a World Cup to set the first one.</p>`;
  const mine=rows.find(r=>r.me),show=full?rows:rows.slice(0,3);let h=show.map(lbRowHTML).join("");
  if(!full&&mine&&mine.rank>3)h+=`<div class="lb-gap">···</div>`+lbRowHTML(mine);
  if(LB.canWrite===false)h+=`<div class="lb-note warn acc-nudge"><span>Sign in with Google to put your best score on the global leaderboard. Your progress is kept on this device until then.</span><button class="acc-btn" data-act="signin">SIGN IN</button></div>`;
  else if(!mine)h+=`<p class="lb-note">${best?"Saving your score…":"Finish a World Cup to get on the board."}</p>`;return h;}
function lbPaint(){document.querySelectorAll("[data-lb]").forEach(el=>el.innerHTML=lbHTML(el.dataset.lb==="full"));
  const r=lbRows().find(x=>x.me);document.querySelectorAll("[data-myrank]").forEach(el=>el.textContent=r?`#${r.rank}`:"–");}

