/* ================= Trophy cabinet ================= */
const FIN_RANK={group:0,qf:1,sf:2,final:3,champ:4},FIN_LABEL={group:"Groups",qf:"Quarters",sf:"Semis",final:"Runner-up",champ:"Champions"};
function cabinet(){return store.get("cabinet",{});}
function cabRecord(T){const c=cabinet(),k=T.fmt+"-"+T.year,o=outcomeKey(T),r=c[k]||{best:"group",won:0,played:0};
  r.played++;if(FIN_RANK[o]>FIN_RANK[r.best])r.best=o;if(o==="champ"){r.won++;if(!r.first)r.first=todayStr();}c[k]=r;store.set("cabinet",c);}
/* stylised trophies: ODI = gold globe on three curved columns, T20 = silver cup with a gold band */
function trophyODI(st){const g=st==="won"?"url(#tgG)":st==="near"?"url(#tgS)":"#2A2366",l=st==="won"?"#FFF3B0":st==="near"?"#E2E8F0":"#3C3586";
  return `<svg viewBox="0 0 60 100" aria-hidden="true"><defs><radialGradient id="tgG" cx=".38" cy=".3" r=".75"><stop offset="0" stop-color="#FFF6CF"/><stop offset=".45" stop-color="#FFC93D"/><stop offset="1" stop-color="#B86E00"/></radialGradient>
  <radialGradient id="tgS" cx=".38" cy=".3" r=".75"><stop offset="0" stop-color="#FFFFFF"/><stop offset=".5" stop-color="#B9C2D3"/><stop offset="1" stop-color="#5B657A"/></radialGradient>
  <linearGradient id="tgC" x1="0" x2="1"><stop offset="0" stop-color="#7C8699"/><stop offset=".5" stop-color="#F1F5F9"/><stop offset="1" stop-color="#7C8699"/></linearGradient></defs>
  <rect x="14" y="84" width="32" height="12" rx="2" fill="${st==="none"?"#1E1A4D":"#2B1A0E"}"/><rect x="18" y="80" width="24" height="5" rx="1.5" fill="${st==="none"?"#262063":"#3D2614"}"/>
  <path d="M20 80C16 66 20 56 25 48M30 80V46M40 80C44 66 40 56 35 48" fill="none" stroke="${st==="none"?"#2E2875":"url(#tgC)"}" stroke-width="3.6" stroke-linecap="round"/>
  <circle cx="30" cy="30" r="18" fill="${g}"/><path d="M12.5 30h35M30 12v36M15 21c10 4 20 4 30 0M15 39c10-4 20-4 30 0M30 12c-7 6-7 30 0 36M30 12c7 6 7 30 0 36" fill="none" stroke="${l}" stroke-opacity=".55" stroke-width="1"/></svg>`;}
function trophyT20(st){const g=st==="won"?"url(#ttS)":st==="near"?"url(#ttN)":"#2A2366",b=st==="won"?"#FFC93D":st==="near"?"#94A3B8":"#3C3586";
  return `<svg viewBox="0 0 60 100" aria-hidden="true"><defs><linearGradient id="ttS" x1="0" x2="1"><stop offset="0" stop-color="#9AA5B8"/><stop offset=".45" stop-color="#FFFFFF"/><stop offset="1" stop-color="#7C8699"/></linearGradient>
  <linearGradient id="ttN" x1="0" x2="1"><stop offset="0" stop-color="#4B5468"/><stop offset=".5" stop-color="#A7B0C0"/><stop offset="1" stop-color="#4B5468"/></linearGradient></defs>
  <rect x="15" y="84" width="30" height="12" rx="2" fill="${st==="none"?"#1E1A4D":"#2B1A0E"}"/><path d="M20 84l3-8h14l3 8z" fill="${g}"/>
  <path d="M26 76c0-8 1-12 4-14 3 2 4 6 4 14z" fill="${g}"/>
  <path d="M14 18h32c0 20-6 36-16 44C20 54 14 38 14 18z" fill="${g}"/><rect x="14" y="26" width="32" height="5" fill="${b}"/>
  <ellipse cx="30" cy="18" rx="16" ry="4" fill="${st==="none"?"#3C3586":"#E2E8F0"}"/><circle cx="30" cy="9" r="6" fill="${b}"/><path d="M27 4c2 3 2 7 0 10M33 4c-2 3-2 7 0 10" stroke="${st==="none"?"#2A2366":"#fff"}" stroke-width=".8" fill="none"/></svg>`;}
function cabSlot(fmt,y){const r=cabinet()[fmt+"-"+y],st=!r?"none":r.won?"won":FIN_RANK[r.best]>=2?"near":"tried";
  const tr=(fmt==="odi"?trophyODI:trophyT20)(st==="tried"?"none":st),lab=!r?"Not played":r.won?(r.won>1?`Won ×${r.won}`:"Won"):FIN_LABEL[r.best];
  return `<div class="cb-slot ${st}" title="${FORMATS[fmt].short} World Cup ${y}: ${lab}${r?`, played ${r.played}`:""}">${st==="won"?'<i class="cb-spot"></i>':""}<div class="cb-tr">${tr}</div>${r&&r.won>1?`<span class="cb-x">×${r.won}</span>`:""}<b>${y}</b><small>${lab}</small></div>`;}
function vCabinet(app){const a=store.get("ach",{}),c=cabinet(),oy=Object.keys(FORMATS.odi.ed).map(Number),ty=Object.keys(FORMATS.t20.ed).map(Number);
  const won=f=>Object.keys(c).filter(k=>k.startsWith(f)&&c[k].won).length,tot=Object.values(c).reduce((n,r)=>n+r.won,0);
  const shelf=(f,ys,per)=>{let s="";for(let i=0;i<ys.length;i+=per)s+=`<div class="cb-shelf" style="--n:${per}">${ys.slice(i,i+per).map(y=>cabSlot(f,y)).join("")}</div>`;return s;};
  const nA=Object.keys(a).length;
  app.innerHTML=`<div class="screen cab7">${topbar()}<h2 class="t6">TROPHY <span>CABINET</span></h2>
   <div class="cb-stats"><div><b>${tot}</b><small>WORLD CUPS WON</small></div><div><b>${won("odi")}/${oy.length}</b><small>ODI CUPS</small></div><div><b>${won("t20")}/${ty.length}</b><small>T20 CUPS</small></div></div>
   <div class="cabinet"><div class="cb-crown">DREAM TEAM · HALL OF CHAMPIONS</div>
    <div class="cb-sec"><div class="cb-lbl"><span>ODI WORLD CUP</span><em>50 OVERS</em></div>${shelf("odi",oy,3)}</div>
    <div class="cb-sec"><div class="cb-lbl t20"><span>T20 WORLD CUP</span><em>20 OVERS</em></div>${shelf("t20",ty,5)}</div>
    <i class="cb-glass"></i></div>
   <p class="cb-key"><span class="k won"></span>Won <span class="k near"></span>Final or semis <span class="k none"></span>Still to win</p>
   <div class="statrow"><div class="stat"><b>${store.get("best",0)||"–"}</b><span>Best score</span></div><div class="stat"><b>${store.get("runs",0)}</b><span>Series played</span></div><div class="stat"><b>${store.get("bestOvr",0)||"–"}</b><span>Best XI OVR</span></div></div>
   <details class="panel achd"><summary class="ph">PERSONAL ACHIEVEMENTS<small>${nA} of ${ACH.length} unlocked <i class="chev2">▾</i></small></summary>
    <div class="pb">${ACH.map(([id,ic,n,d])=>`<div class="ach ${a[id]?"on":""}"><i aria-hidden="true">${ic}</i><div><b>${n}</b><span>${d}${a[id]?` Unlocked ${a[id]}.`:""}</span></div></div>`).join("")}</div></details></div>`;
  refreshHUD();}
const _vResultCab=vResult;
vResult=function(app){const first=!S.scored;_vResultCab(app);if(first&&S.T)cabRecord(S.T);};

/* ================= v7.3: flexible XI + team balance ================= */
SLOTS.length=0;
SLOTS.push({id:"o1",role:"O"},{id:"o2",role:"O"},{id:"m1",role:"M"},{id:"a1",role:"A"},{id:"s1",role:"S"},{id:"f1",role:"F"},{id:"f2",role:"F"},
  {id:"x1",role:"X"},{id:"x2",role:"X"},{id:"x3",role:"X"},{id:"x4",role:"X"});
[GPOS,SPOTS].forEach(o=>Object.keys(o).forEach(k=>delete o[k]));
Object.assign(GPOS,{o1:[146,150],o2:[240,150],x1:[50,240],x2:[344,240],a1:[128,292],m1:[258,292],s1:[70,404],x3:[320,404],f1:[96,520],f2:[295,520],x4:[195,571]});
Object.assign(SPOTS,{o1:[40,14],o2:[60,14],x1:[15,36],a1:[33,36],m1:[67,36],x2:[85,36],s1:[24,61],x4:[50,62],x3:[76,61],f1:[38,85],f2:[62,85]});
/* a keeper heads for the flex spot behind the stumps; everyone else fills the side flex spots first */
function slotFor(p){const free=s=>!S.picks[s.id],own=SLOTS.find(s=>s.role===p.role&&free(s));if(own)return own;
  const flex=SLOTS.filter(s=>s.role==="X"&&free(s));if(!flex.length)return null;
  return p.role==="W"?(flex.find(s=>s.id==="x4")||flex[0]):(flex.find(s=>s.id!=="x4")||flex[0]);}
function assignSlots(xi){const out={},left=[...xi];
  const put=t=>SLOTS.forEach(s=>{if(out[s.id])return;const i=left.findIndex(p=>t(s,p));if(i>=0){out[s.id]=left[i];left.splice(i,1);}});
  put((s,p)=>s.role===p.role);put((s,p)=>s.id==="x4"&&p.role==="W");put(s=>s.role==="X");put(()=>true);return out;}
/* team balance: keeper, 6 batters, 5 bowling options (all-rounders count for both) */
const BAL={wk:3,bowl:2,bat:1.5,needBat:6,needBowl:5};
function balanceOf(xi){const ps=xi.filter(Boolean),n=r=>ps.filter(p=>r.includes(p.role)).length,wk=n("W"),bat=n("OMWA"),bowl=n("SFA"),iss=[];
  if(!wk)iss.push({k:"wk",pen:BAL.wk,t:"No wicketkeeper",d:"A stand-in keeper drops catches and gives away byes."});
  if(bowl<BAL.needBowl){const m=BAL.needBowl-bowl;iss.push({k:"bowl",pen:BAL.bowl*m,t:`Only ${bowl} bowling options`,d:`Part-time bowlers have to bowl ${m===1?"one bowler's":m+" bowlers'"} overs.`});}
  if(bat<BAL.needBat){const m=BAL.needBat-bat;iss.push({k:"bat",pen:BAL.bat*m,t:`Only ${bat} batters`,d:"The tail is in early and has to bat long."});}
  return {wk,bat,bowl,iss,pen:iss.reduce((s,i)=>s+i.pen,0)};}
function rateXI(xi){
  const bats=xi.map(batVal).sort((a,b)=>b-a).slice(0,7),bowls=xi.map(bowlVal).sort((a,b)=>b-a).slice(0,5);
  const bat=wavg(bats,[1.2,1.2,1.1,1,1,.8,.7]),bowl=wavg(bowls,[1.1,1.1,1,1,.8]),bal=balanceOf(xi);
  return {bat:Math.round(bat),bowl:Math.round(bowl),ovr:Math.round(((bat+bowl)/2-bal.pen)*10)/10,bal};}
