function accAvatar(u,cls){return u&&u.picture?`<img class="${cls}" src="${esc(u.picture)}" alt="" referrerpolicy="no-referrer">`:`<span class="${cls} ini">${esc(((u&&u.name)||"P")[0].toUpperCase())}</span>`;}
