/* Duel links: https://…/#duel=DT1-… opens the challenge (or result) straight away */
function consumeDuelLink(){let code=null;
  const m=location.hash.match(/^#duel=(.+)$/);if(m){try{code=decodeURIComponent(m[1]);}catch(e){}history.replaceState(null,"",location.pathname+location.search);}
  if(code)store.set("pendingDuel",code);
  if(!myTeam())return;const p=store.get("pendingDuel",null);if(!p)return;store.set("pendingDuel",null);
  const d=decodeDuel(p);if(!d){toast("That duel link looks incomplete.");return;}
  setTimeout(()=>{if(d.guest){S.screen="duel";S.runId++;window.scrollTo(0,0);openResultCode(d);return;}
    const own=dGet(d.id);if(own&&own.role==="host"){S.duelView={v:"room",id:d.id};go("duel");return;}
    if(own&&own.role==="guest"){S.duelView={v:own.oppTeam&&own.myTeam?"match":"hub",id:d.id};go("duel");return;}
    S.duelView={v:"join",d};go("duel");},60);}
if(/^#duel=/.test(location.hash))setTimeout(()=>{if(!myTeam()){const m=location.hash.match(/^#duel=(.+)$/);try{store.set("pendingDuel",decodeURIComponent(m[1]));}catch(e){}history.replaceState(null,"",location.pathname);}},0);

/* Live/inbox availability follows the server connection */
